    public static ImageSource? Image(string? definitionId, string? accent) =>
        Image(definitionId, ServiceBadge.BrushFor(accent));

    public static ImageSource? Image(string? definitionId, Brush brush)
    {
        if (definitionId is null || !Paths.TryGetValue(definitionId, out var data))
        {
            return null;
        }

        Geometry geometry;
        try
        {
            geometry = Geometry.Parse(data);
        }
        catch (FormatException)
        {
            return null;
        }

        var drawing = new GeometryDrawing(brush, null, geometry);
        var image = new DrawingImage(drawing);
        image.Freeze();
        return image;
    }

    public static FrameworkElement Create(string? definitionId, string name, string? accent, double size = 28)
    {
        var source = Image(definitionId, accent);

        if (source is null)
        {
            return ServiceBadge.Create(name, accent, size);
        }

        return new Image
        {
            Source = source,
            Width = size,
            Height = size,
            Stretch = Stretch.Uniform,
            VerticalAlignment = VerticalAlignment.Center,
        };
    }
